import{_ as r,C as c,o as s,c as l,j as a,a as d,E as t,a2 as i}from"./chunks/framework.BxGh02fV.js";const g=JSON.parse('{"title":"Team loop","description":"","frontmatter":{"title":"Team loop"},"headers":[],"relativePath":"en/agent/boucle-equipe.md","filePath":"en/agent/boucle-equipe.md"}'),n={name:"en/agent/boucle-equipe.md"};function h(p,e,f,u,m,b){const o=c("Ask");return s(),l("div",null,[e[0]||(e[0]=a("h1",{id:"team-loop",tabindex:"-1"},[d("Team loop "),a("a",{class:"header-anchor",href:"#team-loop","aria-label":'Permalink to "Team loop"'},"​")],-1)),e[1]||(e[1]=a("p",null,"This path is for moving a story, an epic or a workshop of evolutions forward through a three-role loop: an analyst, a senior developer and a QA engineer take turns on the OPALE pipe. You come here when you want the agent to chain the work instead of driving it step by step.",-1)),e[2]||(e[2]=a("p",null,"The engine does not run any agent itself: it returns the contract for the next act, your agent runs it (with a sub-agent if it has one), then reports the result.",-1)),e[3]||(e[3]=a("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[d("What you ask the agent "),a("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),t(o,{say:"Start the team loop on the current epic.",verb:"effortless_crew_init",family:"boucle-equipe",args:'{"goal":"the current epic"}'}),t(o,{say:"Run the team on this story only, with pnpm test and pnpm lint as the bar.",verb:"effortless_crew_init",family:"boucle-equipe",args:'{"goal":"this story only","bar":{"test":"pnpm test","lint":"pnpm lint"}}'}),t(o,{say:"Where is the loop? Who has to act now?",verb:"effortless_crew_status",family:"boucle-equipe"}),t(o,{say:"Show me the full trace of what happened in the loop.",verb:"effortless_crew_status",family:"boucle-equipe",args:'{"full":true}'}),t(o,{say:"Classify task TSK-03 as complex, deep tier, high effort, and tell me which model that gives.",verb:"effortless_task_classify",family:"boucle-equipe",args:'{"task_id":"TSK-03","complexity":"complex","capability_tier":"deep","effort_level":"high"}'}),t(o,{say:"Generate a provider profile from the claude preset, for this project only.",verb:"effortless_provider_profile_init",family:"boucle-equipe",args:'{"family":"claude","scope":"project"}'}),t(o,{say:"Show me the available provider presets and my current profile.",verb:"effortless_provider_presets_list",family:"boucle-equipe"}),t(o,{say:"Start the autonomous loop on the simple tasks of the backlog.",verb:"effortless_loop_init",family:"boucle-equipe",args:'{"goal":"the simple tasks of the backlog"}'}),e[4]||(e[4]=i('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="start-the-team-loop" tabindex="-1">Start the team loop <a class="header-anchor" href="#start-the-team-loop" aria-label="Permalink to &quot;Start the team loop&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#crew-init"><code>effortless_crew_init</code></a> takes <code>goal</code> (the objective, repeated in every role&#39;s brief) and <code>scope</code>: <code>story</code>, <code>epic</code> (default), <code>all</code> or <code>workshop</code>. <code>max_rounds</code> (100 by default) and <code>max_epics</code> (3 by default) cap the loop; <code>0</code> means unlimited.</li><li><code>bar</code> declares the mechanical bar: an object that maps a name (<code>test</code>, <code>lint</code>, <code>typecheck</code>, <code>build</code>) to a command, or to an object with <code>command</code> and optionally <code>cwd</code> or <code>stack</code>. At least one command is needed, and it must be runnable: an unmeasured command would never be green and QA could never return <code>go</code>.</li><li><code>force: true</code> overwrites a loop that is already initialized.</li><li>With scope <code>all</code>, when there is no epic left to deliver, the loop enters the evolutions workshop and graduates an axis into the next epic, up to <code>max_epics</code>.</li></ol><h3 id="run-one-round-of-the-loop" tabindex="-1">Run one round of the loop <a class="header-anchor" href="#run-one-round-of-the-loop" aria-label="Permalink to &quot;Run one round of the loop&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#crew-step"><code>effortless_crew_step</code></a> returns the contract for the current act: which role must act, the recommended model and effort, the expected output, and <code>prompt_path</code>, the path of a file that holds the brief (a <code>prompt</code> key). The agent reads that file before starting the sub-agent. Called twice, <code>effortless_crew_step</code> returns the same thing twice: it advances nothing. <code>document</code> targets a specific framing document.</li><li>The role performs the act.</li><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#crew-report"><code>effortless_crew_report</code></a> reports the result: <code>role</code> (<code>analyst</code>, <code>developer</code> or <code>qa</code>, the one the step expects), <code>verdict</code> (<code>done</code> for the analyst and the developer, <code>go</code> or <code>no-go</code> for QA), <code>summary</code>, and <code>payload</code> (the role&#39;s structured output). For a payload too large to pass inline, <code>payload_path</code> points to a JSON file instead, never both.</li><li><code>effortless_crew_report</code> measures the mechanical bar before returning; the call can be long. It returns the next act directly.</li><li>At delivery, the engine itself commits the task&#39;s work, then the closure. It repeats the round until the scope is covered or a cap is reached. Three <code>no-go</code> in a row stop the loop.</li></ol><h3 id="follow-the-loop" tabindex="-1">Follow the loop <a class="header-anchor" href="#follow-the-loop" aria-label="Permalink to &quot;Follow the loop&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#crew-status"><code>effortless_crew_status</code></a> reads the state without changing anything: step, expected role, epic / story / task pointer, counters, caps, end reason (<code>scope_covered</code>, <code>epics_exhausted</code> or <code>rounds_exhausted</code>, <code>null</code> while the loop runs) and a dated ledger of the acts. By default only the latest acts are returned; <code>full: true</code> returns the full trace.</li></ol><h3 id="route-a-task-to-a-model-tier" tabindex="-1">Route a task to a model tier <a class="header-anchor" href="#route-a-task-to-a-model-tier" aria-label="Permalink to &quot;Route a task to a model tier&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#task-classify"><code>effortless_task_classify</code></a> classifies a task of the active story on one or more axes: <code>complexity</code> (<code>simple</code> or <code>complex</code>), <code>capability_tier</code> (<code>deep</code>, <code>standard</code> or <code>light</code>), <code>effort_level</code> (<code>low</code>, <code>medium</code> or <code>high</code>). At least one is required; an omitted axis is left unchanged.</li><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#task-route-show"><code>effortless_task_route_show</code></a> returns the resolved recommendation: tier and effort, translated into a concrete model and a native effort by your provider profile (project profile first, then global). Without classification, the default is <code>standard</code> / <code>medium</code>. It is a suggestion, never an obligation.</li></ol><h3 id="set-up-providers" tabindex="-1">Set up providers <a class="header-anchor" href="#set-up-providers" aria-label="Permalink to &quot;Set up providers&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#provider-presets-list"><code>effortless_provider_presets_list</code></a> lists the embedded and custom presets.</li><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#provider-profile-show"><code>effortless_provider_profile_show</code></a> reads your active profile.</li><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#provider-profile-init"><code>effortless_provider_profile_init</code></a> (re)generates the profile, a tier × effort matrix, from a preset family: <code>claude</code>, <code>codex</code>, <code>gemini</code>, <code>mistral</code> or a free name. <code>scope</code> is <code>global</code> (default) or <code>project</code>. An existing profile is overwritten only with <code>force: true</code>.</li></ol><h3 id="the-autonomous-loop" tabindex="-1">The autonomous loop <a class="header-anchor" href="#the-autonomous-loop" aria-label="Permalink to &quot;The autonomous loop&quot;">​</a></h3><p>A simpler loop that takes the backlog tasks one by one.</p><ol><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#loop-init"><code>effortless_loop_init</code></a> starts it with a <code>goal</code>.</li><li><a href="/Effortless/en/reference/mcp/boucle-equipe.html#loop-step"><code>effortless_loop_step</code></a> advances it: Plan, Implementation, Acceptance, Delivery. At acceptance it runs <code>test_command</code> (by default, the test cycle of the first stack&#39;s model). An unclassified task must be classified first; a complex task is broken down into simple tasks. When the tests pass, the loop tries to commit the task. After too many acceptance failures, it stops.</li></ol><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>Work moves forward task after task, with one delivery commit per task and a closure when the epic is done.</li><li>A loop state and a timestamped ledger, readable at any time through <code>effortless_crew_status</code>.</li><li>In the app, you follow progress in <a href="/Effortless/en/guide/tasks.html">Tasks</a>, <a href="/Effortless/en/guide/backlog.html">Backlog</a> and <a href="/Effortless/en/guide/dashboard.html">Dashboard</a>.</li><li>A provider profile in your home folder (global profile) or in the project (project profile).</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>The project is in semi-auto mode</td><td>An &quot;execution tool disabled&quot; message, flagged <code>gated</code>, for <code>crew_init</code>, <code>crew_step</code>, <code>crew_report</code>, <code>loop_init</code>, <code>loop_step</code></td><td>Switch the project to full mode.</td></tr><tr><td>Unknown scope</td><td><code>crew:scopeInvalid</code></td><td>Pass <code>scope</code> among <code>story</code>, <code>epic</code>, <code>all</code>, <code>workshop</code>.</td></tr><tr><td>No active epic</td><td><code>crew:noActiveEpic</code></td><td>Activate an epic with <code>effortless_epic_activate</code>, or start again with <code>scope: &quot;workshop&quot;</code>.</td></tr><tr><td>A loop already exists</td><td><code>crew:alreadyInitialized</code></td><td>Pass <code>force: true</code> to overwrite it.</td></tr><tr><td>No bar command</td><td><code>crew:barMissing</code></td><td>Pass <code>bar</code>, for example <code>{&quot;test&quot;: &quot;…&quot;, &quot;lint&quot;: &quot;…&quot;}</code>.</td></tr><tr><td>The bar cannot run</td><td><code>crew:barUnrunnable</code>, which names the faulty executable</td><td>Fix the commands named in <code>bar</code>, then run again.</td></tr><tr><td>Bar <code>cwd</code> absolute or outside the project</td><td><code>crew:barCwdInvalid</code></td><td>Run <code>effortless_crew_init</code> again with a <code>bar.cwd</code> relative to the project root.</td></tr><tr><td>A stack&#39;s path not found</td><td><code>crew:stackPathMissing</code></td><td>Create the named folders, or fix the stack&#39;s <code>path</code> with <code>effortless_stack_add</code>.</td></tr><tr><td>No loop initialized</td><td><code>crew:notInitialized</code></td><td>Run <code>effortless_crew_init</code>.</td></tr><tr><td>Unknown role or verdict</td><td><code>crew:roleUnknown</code> or <code>crew:verdictUnknown</code></td><td>Pass <code>role</code> among <code>analyst</code>, <code>developer</code>, <code>qa</code>; <code>verdict</code> among <code>go</code>, <code>no-go</code>, <code>done</code>.</td></tr><tr><td>The reported role is not the expected one</td><td><code>crew:roleMismatch</code></td><td>Report with the expected role; <code>effortless_crew_step</code> names it.</td></tr><tr><td>Report on a step with no actor</td><td><code>crew:stageHasNoActor</code></td><td>Call <code>effortless_crew_step</code> to learn the act actually expected.</td></tr><tr><td><code>payload</code> and <code>payload_path</code> together</td><td><code>crew:payloadPathEtPayload</code></td><td>Provide only one of the two.</td></tr><tr><td><code>payload_path</code> missing, outside the project, too large or malformed</td><td><code>crew:payloadPathIntrouvable</code>, <code>crew:payloadPathHorsPerimetre</code>, <code>crew:payloadPathTropGros</code>, <code>crew:payloadPathJsonInvalide</code>, <code>crew:payloadPathRacineNonObjet</code></td><td>Point to a JSON file in the project whose root is an object (4 MiB at most).</td></tr><tr><td>Declared code absent from the branch</td><td><code>crew:filesNotIntegrated</code></td><td>Run <code>effortless_worktree_reintegrate</code> from the worktree that holds the work, then report again.</td></tr><tr><td>The delivery commit is refused</td><td><code>crew:commitRefused</code></td><td>Remove the cause git names in the refusal, then report again.</td></tr><tr><td>Delivery interrupted, report from another role</td><td><code>crew:deliveryResumeRequiresQaGo</code></td><td>Resume with the <code>qa</code> / <code>go</code> report that could have started it.</td></tr><tr><td>Provider profile already present</td><td><code>create:providerExists</code></td><td>Pass <code>force: true</code> to overwrite it.</td></tr><tr><td>Invalid profile scope</td><td><code>common:scopeInvalid</code></td><td>Pass <code>scope</code> as <code>global</code> or <code>project</code>.</td></tr><tr><td>Project profile without a project</td><td><code>common:projectNotInitialized</code></td><td>Initialize the project, or target the <code>global</code> scope.</td></tr></tbody></table>',18))])}const y=r(n,[["render",h]]);export{g as __pageData,y as default};
